// ── SLI and Error Budget calculations ─────────────────────────

// Basic availability SLI from request counters
function computeAvailabilitySLI(totalRequests, failedRequests) {
  if (totalRequests === 0) return 1.0; // no traffic = no failures
  return (totalRequests - failedRequests) / totalRequests;
}

console.log(computeAvailabilitySLI(1_000_000, 150)); // 0.99985  (99.985%)
console.log(computeAvailabilitySLI(500_000, 600));   // 0.9988   (99.88%)

// Error budget arithmetic
function errorBudgetMinutes(sloTarget, windowDays) {
  const windowMinutes = windowDays * 24 * 60;
  return (1 - sloTarget) * windowMinutes;
}

const budget = errorBudgetMinutes(0.999, 30);
console.log(`Monthly error budget: ${budget.toFixed(1)} minutes`); // 43.2

// Remaining budget given actual SLI measurement
function remainingBudget(sloTarget, actualSLI, windowDays) {
  const totalBudget  = errorBudgetMinutes(sloTarget, windowDays);
  const actualDowntime = (1 - actualSLI) * windowDays * 24 * 60;
  return totalBudget - actualDowntime;
}

console.log(
  `Remaining budget: ${
    remainingBudget(0.999, 0.9988, 30).toFixed(1)
  } minutes`
); // Actual downtime = 0.12% × 43200 = 51.8 min — budget already OVER

// Burn rate: how fast budget is being consumed vs. expected
function burnRate(sloTarget, currentErrorRate, windowDays, elapsedDays) {
  // Expected error rate to exactly exhaust budget by window end
  const expectedRate = 1 - sloTarget;            // e.g. 0.001
  return currentErrorRate / expectedRate;         // >1 means burning fast
}

const rate = burnRate(0.999, 0.0144, 30, 1); // 1.44% error rate in first day
console.log(`Burn rate: ${rate.toFixed(1)}x`); // 14.4x — P1 alert threshold!
console.log(rate >= 14.4 ? 'FIRE P1 ALERT' : 'Within budget');

// ── Toil tracking + burn rate alerting (Node.js / prom-client) ──
import client from 'prom-client';

// Track manual interventions as toil — gives data to justify automation
const toilCounter = new client.Counter({
  name: 'sre_toil_interventions_total',
  help: 'Count of manual operational interventions — proxy for toil volume',
  labelNames: ['type'],
});

// Track error budget burn for alerting
const errorRateGauge = new client.Gauge({
  name: 'sre_current_error_rate',
  help: 'Current 1-hour error rate (fraction of requests failing)',
});

const SLO_TARGET    = 0.999;                     // 99.9% availability SLO
const BUDGET_RATE   = 1 - SLO_TARGET;            // 0.001 = expected error rate
const P1_BURN_RATE  = 14.4;                      // Exhausts budget in ~2h
const P2_BURN_RATE  = 6.0;                       // Exhausts budget in ~5h

function checkBurnRateAlert(currentErrorRate) {
  const burnRate = currentErrorRate / BUDGET_RATE;
  errorRateGauge.set(currentErrorRate);

  if (burnRate >= P1_BURN_RATE) {
    console.error(`[P1 ALERT] Burn rate ${burnRate.toFixed(1)}x — page on-call NOW`);
    return 'P1';
  } else if (burnRate >= P2_BURN_RATE) {
    console.warn(`[P2 ALERT] Burn rate ${burnRate.toFixed(1)}x — investigate within 1h`);
    return 'P2';
  }
  console.log(`Burn rate ${burnRate.toFixed(2)}x — within budget`);
  return null;
}

// Example: a manual restart function that tracks its own toil
async function restartStalledWorker(workerId) {
  toilCounter.inc({ type: 'worker_restart' });
  console.log(`[TOIL] Manual restart of worker ${workerId} — automate this!`);
  // If this fires > 10x/month: write a liveness probe instead
  await fetch(`/internal/workers/${workerId}/restart`, { method: 'POST' });
}

// Simulate different scenarios
checkBurnRateAlert(0.00001);  // 0.01x — healthy
checkBurnRateAlert(0.006);    // 6.0x  — P2
checkBurnRateAlert(0.015);    // 15.0x — P1!
